 let i=0,j=0,out="",adds=0,dels=0;while(i<n&&j<m){if(x[i]===y[j]){out+=esc(x[i]);i++;j++}else if(L[i+1][j]>=L[i][j+1]){if(x[i].trim()){out+=`<del class="kcs-del">${esc(x[i])}</del>`;dels++}else out+=esc(x[i]);i++}else{if(y[j].trim()){out+=`<ins class="kcs-ins">${esc(y[j])}</ins>`;adds++}else out+=esc(y[j]);j++}}
 while(i<n){if(x[i].trim()){out+=`<del class="kcs-del">${esc(x[i])}</del>`;dels++}else out+=esc(x[i]);i++}while(j<m){if(y[j].trim()){out+=`<ins class="kcs-ins">${esc(y[j])}</ins>`;adds++}else out+=esc(y[j]);j++}
