 let a=e.id?byId(e.id):null;if(!a){a=A(newId(),e.t,e.type,"Draft",e.aud,e.cls,e.svc,e.topic,e.own,e.rvw,NOW,addD(NOW,365),0,0,0,0,e.s,e.links,e.srcs,null,false);a.created=NOW;a.rev=NOW;ART.push(a);e.id=a.id}
